public class DelimitedRecordCodecTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String field(Contact c, int index) {
        if (c == null) {
            return "<null contact>";
        }
        return index == 0 ? c.name() : index == 1 ? c.phone() : c.note();
    }

    static Contact parse(String line) {
        try {
            return DelimitedRecordCodec.fromLine(line);
        } catch (Exception e) {
            System.out.println("FAIL  fromLine threw " + e.getClass().getSimpleName());
            failures++;
            return null;
        }
    }

    public static void main(String[] args) {
        check("plain fields", "Ada|555|ok", DelimitedRecordCodec.toLine(new Contact("Ada", "555", "ok")));
        check("pipe escaped", "Ada\\|Lovelace|555|ok",
                DelimitedRecordCodec.toLine(new Contact("Ada|Lovelace", "555", "ok")));
        check("backslash escaped", "back\\\\slash|555|ok",
                DelimitedRecordCodec.toLine(new Contact("back\\slash", "555", "ok")));
        check("empty fields", "||", DelimitedRecordCodec.toLine(new Contact("", "", "")));

        check("parse plain", "Ada", field(parse("Ada|555|ok"), 0));
        check("parse note", "ok", field(parse("Ada|555|ok"), 2));
        check("parse escaped pipe", "Ada|Lovelace", field(parse("Ada\\|Lovelace|555|ok"), 0));
        check("parse escaped backslash", "back\\slash", field(parse("back\\\\slash|555|ok"), 0));
        check("parse empty fields", "", field(parse("||"), 1));

        Contact tricky = new Contact("a|b\\c", "|", "\\");
        check("round trip tricky name", "a|b\\c", field(parse(DelimitedRecordCodec.toLine(tricky)), 0));
        check("round trip tricky phone", "|", field(parse(DelimitedRecordCodec.toLine(tricky)), 1));
        check("round trip tricky note", "\\", field(parse(DelimitedRecordCodec.toLine(tricky)), 2));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

