public class DelimitedRecordCodec {

    public static String toLine(Contact contact) {
        return escape(contact.name()) + "|" + escape(contact.phone()) + "|" + escape(contact.note());
    }

    private static String escape(String field) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < field.length(); i++) {
            char c = field.charAt(i);
            if (c == '\\' || c == '|') {
                out.append('\\');
            }
            out.append(c);
        }
        return out.toString();
    }

    public static Contact fromLine(String line) {
        String[] fields = new String[3];
        int index = 0;
        StringBuilder current = new StringBuilder();
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c == '\\' && i + 1 < line.length()) {
                current.append(line.charAt(i + 1));
                i++;
            } else if (c == '|' && index < 2) {
                fields[index] = current.toString();
                index++;
                current.setLength(0);
            } else {
                current.append(c);
            }
        }
        fields[index] = current.toString();
        for (int i = 0; i < fields.length; i++) {
            if (fields[i] == null) {
                fields[i] = "";
            }
        }
        return new Contact(fields[0], fields[1], fields[2]);
    }
}
